import{_ as e}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as n,o as a,af as o}from"./chunks/mermaid.DEOxUarQ.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const g=JSON.parse(`{"title":"Tencent Hunyuan learning map","description":"Hunyuan (Tencent Hy) is Tencent's model and open-capability line. It is not Yuanbao and not CodeBuddy. This directory covers models, TokenHub, and open weights only.","frontmatter":{"title":"Tencent Hunyuan learning map","description":"Hunyuan (Tencent Hy) is Tencent's model and open-capability line. It is not Yuanbao and not CodeBuddy. This directory covers models, TokenHub, and open weights only.","domain":"product","tags":["hunyuan","llm-api"],"role":"map"},"headers":[],"relativePath":"products/hunyuan/index.md","filePath":"products/hunyuan/index.md","lastUpdated":1787107158000}`),r={name:"products/hunyuan/index.md"};function s(d,t,l,i,c,h){return a(),n("div",null,[...t[0]||(t[0]=[o(`<h1 id="tencent-hunyuan-learning-map" tabindex="-1">Tencent Hunyuan learning map <a class="header-anchor" href="#tencent-hunyuan-learning-map" aria-label="Permalink to &quot;Tencent Hunyuan learning map&quot;">​</a></h1><blockquote><p><strong>Hunyuan / Tencent Hy</strong> is Tencent&#39;s self-developed model family and the channels that open those models to developers. The research site is <a href="https://hunyuan.tencent.com/" target="_blank" rel="noreferrer">hunyuan.tencent.com</a>. Hosted inference goes through <a href="https://cloud.tencent.com/document/product/1823" target="_blank" rel="noreferrer">TokenHub</a>.</p><p>This directory covers <strong>models and open capabilities only</strong>. Yuanbao, CodeBuddy, WorkBuddy, and ima are sibling products. They get one row on the family map.</p></blockquote><h2 id="product-landscape" tabindex="-1">Product landscape <a class="header-anchor" href="#product-landscape" aria-label="Permalink to &quot;Product landscape&quot;">​</a></h2><p>Several Tencent doors share the words Hunyuan or Hy. They are <strong>not</strong> one product with four skins.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Tencent AI (Hunyuan-related official surfaces)</span></span>
<span class="line"><span>├── Hunyuan / Hy — models, research, open weights (this handbook)</span></span>
<span class="line"><span>│   ├── Hy models (Hy3, Hy-MT2, image / video / 3D / vision / ASR)</span></span>
<span class="line"><span>│   ├── Research (Hy3 note, Hyra, …)</span></span>
<span class="line"><span>│   ├── Co-design / International (site chrome, not a call surface)</span></span>
<span class="line"><span>│   ├── Try Hy (Hy AI Studio)</span></span>
<span class="line"><span>│   └── Open weights (GitHub Tencent-Hunyuan / Hugging Face tencent/Hy3)</span></span>
<span class="line"><span>├── TokenHub — cloud model gateway (serves Hy and third-party models)</span></span>
<span class="line"><span>├── Tencent Hunyuan LLM (cloud product 1729, older API tree)</span></span>
<span class="line"><span>├── Yuanbao — consumer assistant (runs Hy3)     → issue #76</span></span>
<span class="line"><span>├── CodeBuddy — coding IDE / CLI                → issue #78</span></span>
<span class="line"><span>├── WorkBuddy — office agent</span></span>
<span class="line"><span>└── ima — knowledge steward</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Surface</th><th>What it is</th><th>Official URL</th><th>This site</th></tr></thead><tbody><tr><td><strong>Hy models / Hunyuan site</strong></td><td>Model and research home</td><td><a href="https://hunyuan.tencent.com/" target="_blank" rel="noreferrer">hunyuan.tencent.com</a></td><td>This page + <a href="./hunyuan.html">tutorial</a></td></tr><tr><td><strong>TokenHub</strong></td><td>Unified LLM API (Hy + third parties)</td><td><a href="https://cloud.tencent.com/product/tokenhub" target="_blank" rel="noreferrer">Product</a> / <a href="https://cloud.tencent.com/document/product/1823" target="_blank" rel="noreferrer">docs 1823</a></td><td><a href="./hunyuan.html">Tutorial</a> / <a href="./hunyuan-cookbook.html">Cookbook</a> / <a href="./hunyuan-cheatsheet.html">Cheatsheet</a></td></tr><tr><td>Try Hy (AI Studio)</td><td>Browser playground</td><td><a href="https://aistudio.tencent.com/" target="_blank" rel="noreferrer">aistudio.tencent.com</a></td><td>One tutorial section</td></tr><tr><td>Open weights</td><td>Apache-2.0 checkpoints</td><td><a href="https://github.com/Tencent-Hunyuan" target="_blank" rel="noreferrer">Tencent-Hunyuan</a> / <a href="https://huggingface.co/tencent/Hy3" target="_blank" rel="noreferrer">tencent/Hy3</a></td><td>Tutorial section + cheatsheet</td></tr><tr><td>Research</td><td>Tech notes</td><td><a href="https://hunyuan.tencent.com/research" target="_blank" rel="noreferrer">research</a> / <a href="https://hy.tencent.com/research/hy3" target="_blank" rel="noreferrer">Hy3</a></td><td>Map row</td></tr><tr><td>Co-design / International</td><td>First-level site nav</td><td><a href="https://hunyuan.tencent.com/" target="_blank" rel="noreferrer">hunyuan.tencent.com</a> header</td><td>Map row; not a new product</td></tr><tr><td>Hunyuan cloud product (1729)</td><td>Older dedicated API tree</td><td><a href="https://cloud.tencent.com/product/hunyuan" target="_blank" rel="noreferrer">product/hunyuan</a> / <a href="https://cloud.tencent.com/document/product/1729" target="_blank" rel="noreferrer">docs 1729</a></td><td>Map row. Hy3 prose lives on TokenHub</td></tr><tr><td>Yuanbao</td><td>All-in-one assistant that already uses Hy3</td><td><a href="https://yuanbao.tencent.com/" target="_blank" rel="noreferrer">yuanbao.tencent.com</a></td><td>Map row → #76</td></tr><tr><td>CodeBuddy</td><td>Tencent Cloud coding assistant</td><td><a href="https://www.codebuddy.cn/" target="_blank" rel="noreferrer">codebuddy.cn</a></td><td>Map row → #78</td></tr><tr><td>WorkBuddy</td><td>Office agent workbench</td><td><a href="https://www.workbuddy.cn/" target="_blank" rel="noreferrer">workbuddy.cn</a> / <a href="https://cloud.tencent.com/product/workbuddy" target="_blank" rel="noreferrer">cloud product</a></td><td>Map row</td></tr><tr><td>ima</td><td>Knowledge-base steward</td><td><a href="https://ima.qq.com/" target="_blank" rel="noreferrer">ima.qq.com</a></td><td>Map row</td></tr><tr><td>Jobs / face ID / CVM / SMS</td><td>Non-topic nav items</td><td>—</td><td><strong>Out of scope</strong></td></tr></tbody></table><p><strong>Name collisions</strong> (full write-up in the <a href="./hunyuan-glossary.html">glossary</a>):</p><ul><li><strong>Hunyuan / Hy ≠ Yuanbao.</strong> The model family is not the consumer chat app.</li><li><strong>Hy3 ≠ TokenHub ≠ AI Studio.</strong> Model, gateway, playground.</li><li><strong>There is no first-party <code>hunyuan</code> CLI.</strong> The coding agent product is CodeBuddy.</li><li><strong>Open-source repo names ≠ TokenHub <code>model</code> slugs.</strong></li></ul><h3 id="quick-decision" tabindex="-1">Quick decision <a class="header-anchor" href="#quick-decision" aria-label="Permalink to &quot;Quick decision&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>What do I want?</span></span>
<span class="line"><span>├── Try Hy3 / translation / multimodal in a browser</span></span>
<span class="line"><span>│   └── → Hy AI Studio (aistudio.tencent.com)</span></span>
<span class="line"><span>├── Call Hunyuan from my own front end / Node service</span></span>
<span class="line"><span>│   └── → TokenHub, model = hy3 (this handbook)</span></span>
<span class="line"><span>├── Point Claude Code / Cursor at Hy3</span></span>
<span class="line"><span>│   └── → TokenHub “connect AI tools”; Hy3 walkthrough is official 1823/131903</span></span>
<span class="line"><span>│       └── CodeBuddy itself is #78, not this directory</span></span>
<span class="line"><span>├── Serve open weights</span></span>
<span class="line"><span>│   └── → github.com/Tencent-Hunyuan/Hy3 (official: 8-GPU class)</span></span>
<span class="line"><span>├── Chat / search / write, no code</span></span>
<span class="line"><span>│   └── → Yuanbao (#76)</span></span>
<span class="line"><span>├── IDE completion / repo agent</span></span>
<span class="line"><span>│   └── → CodeBuddy (#78)</span></span>
<span class="line"><span>└── CVM / COS / SMS</span></span>
<span class="line"><span>    └── → Out of scope</span></span></code></pre></div><p>Sources: <a href="https://hunyuan.tencent.com/" target="_blank" rel="noreferrer">hunyuan.tencent.com</a>, <a href="https://cloud.tencent.com/document/product/1823" target="_blank" rel="noreferrer">TokenHub docs</a>, <a href="https://cloud.tencent.com/document/product/1823/132252" target="_blank" rel="noreferrer">Hy call guide</a>.</p><h2 id="when-this-handbook-is-worth-it" tabindex="-1">When this handbook is worth it <a class="header-anchor" href="#when-this-handbook-is-worth-it" aria-label="Permalink to &quot;When this handbook is worth it&quot;">​</a></h2><p><strong>Read it when</strong></p><ul><li>You want an OpenAI-compatible domestic model from TypeScript, and the official door is TokenHub <code>hy3</code>.</li><li>You already use Claude Code / Cursor and want Hy3 on the same harness (official connect pages exist).</li><li>You need to compare hosted <code>hy3</code> with the open checkpoint.</li></ul><p><strong>Skip it when</strong></p><ul><li>You want Yuanbao the chat app → #76.</li><li>You want CodeBuddy the coding product → #78.</li><li>You want MoE / MTP / attention internals → <a href="./../../tech/fundamentals/LLM.html">LLM fundamentals</a> and <a href="https://llm.zenheart.site/chapters/" target="_blank" rel="noreferrer">Learn LLM</a>.</li></ul><h2 id="learning-path" tabindex="-1">Learning path <a class="header-anchor" href="#learning-path" aria-label="Permalink to &quot;Learning path&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Stage</th><th>Read</th><th>Goal</th></tr></thead><tbody><tr><td>1. Pick a door</td><td>This map</td><td>Stop mixing Yuanbao / TokenHub / Hy3</td></tr><tr><td>2. First call</td><td><a href="./hunyuan.html">Tutorial</a></td><td>A <code>hy3</code> completion in 15 minutes</td></tr><tr><td>3. Wire it in</td><td><a href="./hunyuan-cookbook.html">Cookbook</a></td><td>Streaming, thinking, tools, Claude Code</td></tr><tr><td>4. Look up</td><td><a href="./hunyuan-cheatsheet.html">Cheatsheet</a></td><td>Slugs, prices, endpoints</td></tr><tr><td>5. Names</td><td><a href="./hunyuan-glossary.html">Glossary</a></td><td>Which official tree wins</td></tr></tbody></table><h2 id="model-snapshot-hy-family-slugs-only" tabindex="-1">Model snapshot (Hy-family slugs only) <a class="header-anchor" href="#model-snapshot-hy-family-slugs-only" aria-label="Permalink to &quot;Model snapshot (Hy-family slugs only)&quot;">​</a></h2><p>Canonical table: <a href="https://cloud.tencent.com/document/product/1823/130051" target="_blank" rel="noreferrer">TokenHub model list</a>. Prices: <a href="https://cloud.tencent.com/document/product/1823/130055" target="_blank" rel="noreferrer">pricing</a> (2026-08-14).</p><table tabindex="0"><thead><tr><th>Official name</th><th><code>model</code></th><th>Window (in / out)</th><th>Official one-liner</th></tr></thead><tbody><tr><td>Hy3</td><td><code>hy3</code></td><td>192k / 128k (256k context)</td><td>Real-world Coding / long-context / Agent</td></tr><tr><td>Hy3 preview</td><td><code>hy3-preview</code></td><td>same</td><td><strong>Retires 2026-08-31</strong></td></tr><tr><td>Hy-MT2-Pro / Plus / Lite</td><td><code>hy-mt2-*</code></td><td>4k / 4k</td><td>Translation</td></tr><tr><td>Hy-Role / Latest</td><td><code>hy-role</code> / <code>hunyuan-role-latest</code></td><td>28k / 4k</td><td>Role-play</td></tr><tr><td>HY-Image-V3.0</td><td><code>hy-image-v3.0</code></td><td>—</td><td>T2I / I2I</td></tr><tr><td>HY-3D-3.1</td><td><code>hy-3d-3.1</code></td><td>—</td><td>T23D / I23D</td></tr></tbody></table><p>Hosted Hy3: <strong>1 / 4 / 0.25</strong> CNY per million tokens (input / output / cache hit). Open weights are a separate path: <a href="./hunyuan.html#open-weights">tutorial</a>.</p><h2 id="out-of-scope" tabindex="-1">Out of scope <a class="header-anchor" href="#out-of-scope" aria-label="Permalink to &quot;Out of scope&quot;">​</a></h2><ul><li>Full Yuanbao / CodeBuddy / WorkBuddy / ima tutorials.</li><li>Picking DeepSeek / Kimi / GLM on TokenHub.</li><li>Non-AI Tencent Cloud (CVM, COS, SMS, domains).</li><li>Model internals.</li></ul><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./hunyuan.html">Tutorial</a></li><li><a href="./hunyuan-cookbook.html">Cookbook</a></li><li><a href="./hunyuan-cheatsheet.html">Cheatsheet</a></li><li><a href="./hunyuan-glossary.html">Glossary</a></li><li><a href="./../../tech/fundamentals/LLM.html">LLM fundamentals</a></li><li><a href="./../ai-coding/">All products</a></li></ul>`,26)])])}const f=e(r,[["render",s]]);export{g as __pageData,f as default};
